{
  "spells": [
    {
      "id": "spell_light_10",
      "theory": "斑痕追照将魔力送入一块树脂，使其在短距离内以散射光扫过器物或地面，近几日留下的污痕会略微吸光显出深色轮廓。光只映出痕迹的所在，不显示形状细节，也不指出留下痕迹的人是谁。树脂需先含在口中润湿，使表面黏性足以附着魔力；作用范围不超过二十米，持续九十息。",
      "casting": "把树脂置舌下润湿，以拇指在掌心画分叉纹，随后将树脂弹出，落地前完成分叉纹的收笔。",
      "failure": "树脂落地碎裂，光只闪一下便灭，或污痕显示成整片灰影，无法辨认大致位置。已耗魔力不返。",
      "counters": [
        "用湿布覆盖可疑表面，水膜使散射光无法附着，污痕暂不显影。",
        "在目标区域撒一层细灰，灰粒先吸光，追照只照出灰层轮廓。"
      ],
      "socialConsequences": "河谷乡约请人验看谷仓或院门附近是否有人近期翻动，常愿付少量树脂作酬。城中公会检查货栈时也雇人施此术，但被查一方若认为范围越界，可要求施术者只照指定区域。港口理货人用其核对甲板污渍以判断装卸顺序，货主则担心痕迹被误读为自家过失，往往要求乡约或港务小吏在场见证。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时常把旧痕与近日痕混在一起，需反复对照。",
        "百点后能稳定区分两日内的污痕与更早的痕迹。",
        "三百点后光扫过时不再留下跳动的光斑，判读更可靠。",
        "六百点以上可控制光只扫过指定半米见方，精度稳定。"
      ]
    },
    {
      "id": "spell_light_11",
      "theory": "折光衣以树脂为媒，将魔力铺在受术者外衣表面，使轮廓边缘的光线轻微偏折。远处看身形会与背景混同，但移动过快或雨水打湿衣料时，偏折层会开裂失效。此术只影响一人，范围二十米内施术者须能看见目标，持续九十息，不改变气味、声音或足迹。",
      "casting": "捏碎树脂抹于目标外衣肩部，同时以食指沿衣缝向下画一道折线，画满即收手。",
      "failure": "折线画到一半断开，目标轮廓忽隐忽现，反而比平时更显眼，雨水一打便彻底失效。",
      "counters": [
        "向可疑轮廓撒一把干沙，沙粒会卡在偏折层边缘显出衣料轮廓。",
        "用强侧光从低处斜照，偏折层在逆光下会留下淡色边线。"
      ],
      "socialConsequences": "河谷猎户在近林追迹时偶尔请人施此术，以免惊走猎物，但乡约要求施术前让同行者知晓，免得误伤。城中巡夜队不鼓励在街巷使用，因轮廓忽隐易被当作窃贼；公会登记过的护卫在货场值夜时可申请使用。港口装卸工在雨前赶工时会拒绝，因雨水一打术即失效，反惹人注意。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时偏折层只覆盖半身，走动几步便露出腿脚。",
        "百点后能稳定维持全身轮廓，慢走时不轻易开裂。",
        "三百点后雨水打湿外层仍需重施，但开裂前有短暂预警。",
        "六百点以上可让偏折层贴着衣缝走，静止时几乎不显边。"
      ]
    },
    {
      "id": "spell_light_12",
      "theory": "破雾光借助树脂燃烧时散出的细光尘，使薄雾中的水珠短暂减少散射，二十米内视线变得清晰。浓雾中光尘只能穿透一小段距离，超出范围仍是一片白茫。光尘不驱散雾，也不照亮雾外，持续九十息后自行沉降。",
      "casting": "将树脂夹在拇指与中指间搓热，向身前雾气弹指三次，每次弹出一缕光尘。",
      "failure": "光尘凝成团坠地，雾中只留一圈更暗的环，视线反而比施术前更差。",
      "counters": [
        "向光尘团泼一捧水，水珠重新增多，清晰区立即缩回原状。",
        "用长杆在雾中搅动，气流打散光尘，薄雾恢复原有浓度。"
      ],
      "socialConsequences": "河谷渡口在晨雾中发船前，船夫会凑钱请人弹一次破雾光，以便看清近岸礁石。城中钟楼守夜人用其核对远处火号，但公会提醒不可依赖它替代烽火。港口引水员在薄雾天最欢迎此术，浓雾天则直接停航。货主若因雾误期，港务会追问是否已用破雾光确认近处航道。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时弹出的光尘散得太开，清晰区只有两三步远。",
        "百点后光尘落点更准，能稳定清出十米左右的薄雾通道。",
        "三百点后弹指力度均匀，清晰区边缘不再突然变暗。",
        "六百点以上可在浓雾边缘维持一小段清晰，浓雾仍无法穿透。"
      ]
    }
  ]
}
